import json

original = [[8, 8, 6], [6, 3, 6], [6, 8, 8]]

# Already tried 90° and 270°, let me try more
# What about patterns based on sum, product, XOR, etc.?

# XOR of neighbor values?
xor_neighbors = [[0]*3 for _ in range(3)]
for i in range(3):
    for j in range(3):
        neighbors = []
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < 3 and 0 <= nj < 3:
                neighbors.append(original[ni][nj])
        if neighbors:
            xor_neighbors[i][j] = neighbors[0]
            for x in neighbors[1:]:
                xor_neighbors[i][j] ^= x

action = {"action": "submit", "grid": xor_neighbors}
print("XOR neighbors:", json.dumps(xor_neighbors))

# Or simply average (integer division)
avg = [[(sum(original[i][j] for di,dj in [(-1,0),(1,0),(0,-1),(0,1)] if 0<=i+di<3 and 0<=j+dj<3) // 4) for j in range(3)] for i in range(3)]
action = {"action": "submit", "grid": avg}
print("Average neighbors:", json.dumps(avg))
